module monotone_seq_generator(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] N,\n    input [7:0] K,\n    output reg [7:0] data,\n    output reg [7:0] index,\n    output reg valid,\n    output reg done,\n    output reg error\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT        = 3'd1;\n    localparam [2:0] LOAD_VALUES = 3'd2;\n    localparam [2:0] OUTPUT      = 3'd3;\n    localparam [2:0] DONE_ST     = 3'd4;\n    localparam [2:0] ERROR_ST    = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [7:0] N_reg, K_reg;\n    reg [7:0] q, r;\n    reg [7:0] min_K;\n    reg [7:0] cycle_count;\n    reg [7:0] seq_counter;\n    reg [7:0] sequence [0:15];\n    integer i;\n\n    // Reset and state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            data <= 8'd0;\n            index <= 8'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n            error <= 1'b0;\n            cycle_count <= 8'd0;\n            N_reg <= 8'd0;\n            K_reg <= 8'd0;\n            seq_counter <= 8'd0;\n            for (i = 0; i < 16; i = i + 1) sequence[i] <= 8'd0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    error <= 1'b0;\n                    valid <= 1'b0;\n                    seq_counter <= 8'd0;\n                    if (start) begin\n                        N_reg <= N;\n                        K_reg <= K;\n                    end\n                end\n\n                INIT: begin\n                    // Calculate min_K = ceil(sqrt(N))\n                    if (N_reg <= 8'd1)       min_K <= 8'd1;\n                    else if (N_reg <= 8'd4)  min_K <= 8'd2;\n                    else if (N_reg <= 8'd9)  min_K <= 8'd3;\n                    else                     min_K <= 8'd4;\n\n                    q <= N_reg / K_reg;\n                    r <= N_reg % K_reg;\n                    cycle_count <= 8'd0;\n                end\n\n                LOAD_VALUES: begin\n                    // Calculate element value\n                    reg [7:0] block_num = 8'd0;\n                    reg [7:0] cumul_size = 8'd0;\n                    for (i = 0; i < K_reg; i = i + 1) begin\n                        if (cycle_count >= cumul_size) begin\n                            block_num = i;\n                            cumul_size = cumul_size + ((i < r) ? (q + 8'd1) : q);\n                        end\n                    end\n\n                    reg [7:0] base = 1 + block_num * q + ((block_num < r) ? block_num : r);\n                    reg [7:0] rel_pos = cycle_count - (cumul_size - ((block_num < r) ? (q + 8'd1) : q));\n                    sequence[cycle_count] <= base + ((block_num < r) ? (q + 8'd1) : q) - 8'd1 - rel_pos;\n\n                    cycle_count <= cycle_count + 8'd1;\n                end\n\n                OUTPUT: begin\n                    data <= sequence[seq_counter];\n                    index <= seq_counter;\n                    valid <= 1'b1;\n                    seq_counter <= seq_counter + 8'd1;\n                end\n\n                DONE_ST: done <= 1'b1;\n                ERROR_ST: {done, error} <= {1'b1, 1'b1};\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:      next_state = (start) ? INIT : IDLE;\n            INIT:      begin\n                if ((K_reg < min_K) || (K_reg > N_reg)) next_state = ERROR_ST;\n                else if (N_reg == 8'd0)               next_state = DONE_ST;\n                else                                     next_state = LOAD_VALUES;\n            end\n\n            LOAD_VALUES: \n                if (cycle_count == N_reg - 1) next_state = OUTPUT;\n\n            OUTPUT: \n                if (seq_counter == N_reg - 1) next_state = DONE_ST;\n\n            DONE_ST:  next_state = DONE_ST;\n            ERROR_ST: next_state = ERROR_ST;\n            default:  next_state = IDLE;\n        endcase\n    end\n\nendmodule